import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { HttpClient } from '@angular/common/http';
import { map, tap, catchError } from 'rxjs/operators';
import { ServiceRequesterService } from '../../utils/restServiceClient/service-requester.service';
import { UserModel, UserSignInModel, UserSignUpModel, UserSupportModel } from '../interfaces/user-model';

@Injectable({
  providedIn: 'root'
})
export class AuthenticationService {

  private currentUserSubject: BehaviorSubject<UserModel | null>;
  public currentUser: Observable<UserModel | null>;

  constructor(
    private http: HttpClient,
    private _restService: ServiceRequesterService
  ) {
    this.currentUserSubject = new BehaviorSubject<UserModel | null>(JSON.parse(localStorage.getItem('currentUser') as string));
    this.currentUser = this.currentUserSubject.asObservable();
  }

  public get currentUserValue(): UserModel | null {
    if (this.currentUserSubject.value == null) {
      this.currentUserSubject = new BehaviorSubject<UserModel | null>(JSON.parse(localStorage.getItem('currentUser') as string));
    }
    return this.currentUserSubject.value;
  }

  public get guestUserValue(): UserModel {
    return {
      id: 0,
      name: 'Guest',
      cookie: '',
      usercredit: '',
      userstring: '',
      success: false,
      status: 'Not loggedin',
      ops: 'Dummy local data'
    } as UserModel;
  }

  signIn(username: string, password: string) {
    let param: UserSignInModel = { useremail: '', userpassword: '' };
    param["useremail"] = username;
    param['userpassword'] = password;
    return this._restService.getNonce('validateLogin', param, 'dtusers')
      .pipe(
        tap(data => {
          console.log('fetched User from here ' + JSON.stringify(data));
          // {"status":"ok","id":"3","cookie":"45bf8eb634943efe7a73d0816a7d69a72995bcd7","usercredit":"0","userstring":"1-1-10:2-1-0:3-0-0:4-0-0:5-0-0","name":"abc1 xyz1","ops":"login done","success":true}
          if (data && data['success'] && data['cookie']) {
            if (param["useremail"] == 'dtdm.app@gmail.com' || param["useremail"] == 'devtrip.dev@gmail.com') {
              if (data['usercredit'] == 0) {
                data['usercredit'] = 1000;
              }
            }
            localStorage.setItem('currentUser', JSON.stringify(data));
            this.currentUserSubject.next(data);
          } else {
            this.handleError('updateUser', []);
          }
          return data;
        }),
        catchError(this.handleError('updateUser', []))
      );
  }

  getUserProfileData() {
    let user = {
      id: this.currentUserValue?.id
    }
    return this._restService.getNonce('getUserData', user, 'dtusers')
      .pipe(
        tap(data => console.log('updated User from here ' + JSON.stringify(data))),
        catchError(this.handleError('updateUser', []))
      );
  }

  updateUser(firstname: string, lastname: string, useraddress: string, usercountery: string) {

    let user = {
      id: this.currentUserValue?.id,
      firstname: firstname,
      lastname: lastname,
      useraddress: useraddress,
      usercountery: usercountery
    }

    return this._restService.getNonce('updateUserData', user, 'dtusers')
      .pipe(
        tap(data => {
          console.log('updated User from here ' + JSON.stringify(data));
          this.patchUserValues(data);
        }),
        catchError(this.handleError('updateUser', []))
      );
  }

  updateUserSettings(credential: any, email: any, notification: any, contact: any, reminder: any) {
    let userSettings = {
      id: this.currentUserValue?.id,
      credential: credential,
      email: email,
      notification: notification,
      contact: contact,
      reminder: reminder
    }

    return this._restService.getNonce('updateUserSettings', userSettings, 'dtusers')
      .pipe(
        tap(data => {
          console.log('updated User setings from here ' + JSON.stringify(data));
          this.patchUserValues(data);
        }),
        catchError(this.handleError('updateUserSettings', []))
      );

  }

  signOut() {
    // remove user from local storage to log user out
    localStorage.removeItem('currentUser');
    this.currentUserSubject.next(null);
    console.log('From Logout', this.currentUserSubject.value);
  }

  signUp(firstname: string, lastname: string, email: string, password: string, phonenumber: string, useraddress: string, usercountery: string): Observable<any> {
    let param: UserSignUpModel = { firstname: '', lastname: '', useremail: '', userpassword: '', userphone: '', useraddress: '', usercountery: '', userstring: '', userstatus: 0, usercredit: 0 };
    param.firstname = firstname;
    param.lastname = lastname;
    param.useremail = email;
    param.userpassword = password;
    param.userphone = phonenumber;
    param.useraddress = useraddress;
    param.usercountery = usercountery;
    param.userstring = '1-1-0:2-0-0:3-0-0:4-0-0:5-0-0';
    param.userstatus = 1;
    param.usercredit = 0;

    return this._restService.getNonce('registeruser', param, 'dtusers')
      .pipe(
        tap(data => {
          //console.log('fetched User from registered '+ JSON.stringify(data))
          if (data && data['success'] && data['cookie']) {
            localStorage.setItem('currentUser', JSON.stringify(data));
            this.currentUserSubject.next(data);

          } else {
            this.handleError('updateUser', []);
          }
          return data;
        }),
        catchError(this.handleError('updateUser', []))
      )
  }

  sendMail(name: string, email: string, phone: string, subject: string, message: string): Observable<any> {
    let param: UserSupportModel = { name: '', email: '', phone: '', subject: '', message: '' };
    param.name = name;
    param.email = email;
    param.phone = phone;
    param.subject = subject;
    param.message = message;

    return this._restService.mailSupport(param)
      .pipe(
        tap(data => {
          //console.log('fetched User from registered '+ JSON.stringify(data))
          /*if (data && data['success'] && data['cookie']) {
            
          } else {
            this.handleError('updateUser', []);
          }*/
          return data;
        }),
        catchError(this.handleError('updateUser', []))
      )
  }

  /**
   * Handle Http operation that failed.
   * Let the app continue.
   * @param operation - name of the operation that failed
   * @param result - optional value to return as the observable result
   */
  private handleError<T>(operation = 'operation', result?: T) {
    return (error: any): Observable<T> => {

      // TODO: send the error to remote logging infrastructure
      console.error(error); // log to console instead

      // TODO: better job of transforming error for user consumption
      console.log(`${operation} failed: ${error.message}`);

      // Let the app keep running by returning an empty result.
      return of(result as T);
    };
  }

  private patchUserValues(data: any) {
    let curr = JSON.parse(localStorage.getItem('currentUser') as string);
    curr.name = data.firstname + ' ' + data.lastname;
    localStorage.setItem('currentUser', JSON.stringify({ ...curr, ...data }));
    this.currentUserSubject.next(JSON.parse(localStorage.getItem('currentUser') as string));
  }

}
