  getNonce(str: string, param: Object, ctrl: String): Observable<any> {
    //console.log('here in init service method');
    const url = this._apiUrl + 'nonce/';//this._apiUrl + 'get_nonce/?controller='+ctrl+'&method='+str;
    this._paramObject = param;
    return this._http.get<any>(url)
      .pipe(
        tap(
          data => {
            console.log('fetched nonce from here ' + JSON.stringify(data));
            this._nonceObject = data;
          }
        ),
        mergeMap(_ => {
          switch (str) {
            case 'validateLogin':
              return this.handleLogin();
            case 'updateuserData':
              return this.handleUpdateUserData();
            case 'registeruser':
              return this.handleRegisterUser();
            case 'getUserData':
              return of();// To be handled from PHP
            case 'updateUserData':
              return of();// To be handled from PHP
            case 'updateUserSettings':
              return of();// To be handled from PHP
            default:
              return of(null);

          }
          //return this.getLoginData()
        }),
        catchError(this.handleError('getUser', []))
      );
  }

  private handleRegisterUser(): Observable<any> {

    const url = this._apiUrl + 'user';

    return this._http.post<any>(url, {...this._paramObject, nonce: this._nonceObject?.Nonce || ''})
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data))),
        catchError(this.handleError('RegisterUser', []))
      );
  }

  private handleUpdateUserData(): Observable<any> {
    const url = this._apiUrl + 'user';

    return this._http.put<any>(url, this._paramObject)
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data))),
        catchError(this.handleError('UpdateUserData', []))
      );
  }

  private handleLogin(): Observable<any> {
    
    const params = new HttpParams()
      .set('useremail', this._paramObject['useremail'])
      .set('userpassword', this._paramObject['userpassword'])
      .set('nonce', this._nonceObject?.Nonce || '');
    //const url = this._apiUrl + 'user?useremail=' + this._paramObject['useremail'] + '&userpassword=' + this._paramObject['userpassword'] + '&nonce=' + this._nonceObject?.Nonce;
    //return this._http.get<any>(this._apiUrl + 'user', { params: queryParams })
    return this._http.get<any>(this._apiUrl + 'user', { params: params })
      .pipe(
        tap(data => console.log("received data is " + JSON.stringify(data))),
        catchError(this.handleError('Login', []))
      );
  }

